scenario.irule:
when CLIENT_ACCEPTED {
  set message [RESOLVER::name_lookup /Common/r1 www.example.com. A]
  set question [lindex [DNSMSG::section $message question] 0]
  set answer [lindex [DNSMSG::section $message answer] 0]
  set summary [RESOLVER::summarize $message]
  if {[DNSMSG::header $message qr] != 1 || [DNSMSG::header $message rcode] != 0 || [DNSMSG::record $question owner] ne "www.example.com." || [DNSMSG::record $answer type] ne "A" || [DNSMSG::record $answer rdata] ne "192.0.2.20" || [llength $summary] != 1} { error resolver-dnsmsg-mismatch }
}
